    /// <summary>
    /// Finds the METTMSShipmentRatingUnit record by InventLocationId, shipmentUOM.
    /// </summary>
    /// <param name = "_inventLocationId">InventLocationId</param>
    /// <param name = "_shipmentUOM">ShipmentUOM</param>
    /// <returns>METTMSShipmentRatingUnit buffer</returns>
    public static METTMSShipmentRatingUnit find(InventLocationId _inventLocationId, METShipmentUOM _shipmentUOM, boolean _forUpdate = false)
    {
        METTMSShipmentRatingUnit metTMSShipmentRatingUnit;

        if (_forUpdate)
        {
            metTMSShipmentRatingUnit.selectForUpdate(true);
        }

        if (_inventLocationId && _shipmentUOM)
        {
            select firstonly metTMSShipmentRatingUnit
            where metTMSShipmentRatingUnit.Warehouse == _inventLocationId
            && metTMSShipmentRatingUnit.ShipmentUOM == _shipmentUOM;
        }

        return metTMSShipmentRatingUnit;
    }

/// <summary>
/// Returns a boolean value, Yes if record found otherwise No.
/// </summary>
/// <param name = "_custAccount">Customer number.</param>
/// <returns>A boolean value, Yes if record found otherwise No.</returns>
public static boolean exist(InventLocationId _inventLocationId, METShipmentUOM _shipmentUOM)
{
    return (_inventLocationId && _shipmentUOM) && (select firstonly RecId from METTMSShipmentRatingUnit
                                                    index hint WarehouseIdX
                                                        where METTMSShipmentRatingUnit.Warehouse == _inventLocationId
                                                            && METTMSShipmentRatingUnit.ShipmentUOM == _shipmentUOM).RecId != 0;
}
